WITH latest_metric AS (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14'), positive_candidates AS (SELECT mktcode,tgtcode,MAX(bizdate) AS bizdate FROM `newzl`.`hsj_stock_hq_basic` WHERE volume>0 GROUP BY mktcode,tgtcode), positive_rank AS (SELECT c.mktcode,c.tgtcode,c.bizdate,ROW_NUMBER() OVER(ORDER BY m.volume DESC,c.mktcode,c.tgtcode) AS rn FROM positive_candidates c JOIN latest_metric m ON m.mktcode=c.mktcode AND m.tgtcode=c.tgtcode), negative_candidates AS (SELECT mktcode,tgtcode,MAX(bizdate) AS bizdate FROM `newzl`.`hsj_stock_hq_basic` WHERE volume<0 GROUP BY mktcode,tgtcode), negative_rank AS (SELECT c.mktcode,c.tgtcode,c.bizdate,ROW_NUMBER() OVER(ORDER BY m.volume ASC,c.mktcode,c.tgtcode) AS rn FROM negative_candidates c JOIN latest_metric m ON m.mktcode=c.mktcode AND m.tgtcode=c.tgtcode) SELECT mktcode,tgtcode,bizdate FROM positive_rank WHERE rn=1 UNION SELECT mktcode,tgtcode,bizdate FROM negative_rank WHERE rn=1;
